PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS roles(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS social_ranks(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,min_points INTEGER NOT NULL,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS permissions(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions(role_id INTEGER,permission_id INTEGER,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,dni TEXT UNIQUE,names TEXT NOT NULL,last_names TEXT NOT NULL,username TEXT UNIQUE NOT NULL,email TEXT,phone TEXT,birth_date TEXT,password_hash TEXT NOT NULL,role_id INTEGER NOT NULL,social_rank_id INTEGER,status TEXT NOT NULL DEFAULT 'pending',profile_photo TEXT,authority_type TEXT,bio TEXT DEFAULT '',demo_flag INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id),FOREIGN KEY(social_rank_id) REFERENCES social_ranks(id));
CREATE TABLE IF NOT EXISTS friend_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,sender_id INTEGER NOT NULL,receiver_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(sender_id,receiver_id),FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(receiver_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS friends(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,friend_id INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,friend_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(friend_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER NOT NULL,user_id INTEGER NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS reactions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,post_id INTEGER,comment_id INTEGER,type TEXT NOT NULL,UNIQUE(user_id,post_id,comment_id));
CREATE TABLE IF NOT EXISTS forums(id INTEGER PRIMARY KEY AUTOINCREMENT,category TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,user_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS forum_comments(id INTEGER PRIMARY KEY AUTOINCREMENT,forum_id INTEGER NOT NULL,user_id INTEGER NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT,public_id TEXT UNIQUE NOT NULL,user_id INTEGER NOT NULL,category TEXT NOT NULL,subcategory TEXT,description TEXT NOT NULL,latitude REAL,longitude REAL,priority TEXT NOT NULL DEFAULT 'normal',status TEXT NOT NULL DEFAULT 'created',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS report_history(id INTEGER PRIMARY KEY AUTOINCREMENT,report_id INTEGER NOT NULL,status TEXT NOT NULL,actor_id INTEGER,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(report_id) REFERENCES reports(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS report_evidence(id INTEGER PRIMARY KEY AUTOINCREMENT,report_id INTEGER NOT NULL,file_path TEXT NOT NULL,original_name TEXT,mime TEXT,size INTEGER,FOREIGN KEY(report_id) REFERENCES reports(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS help_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,help_type TEXT NOT NULL,description TEXT NOT NULL,priority TEXT NOT NULL DEFAULT 'normal',latitude REAL NOT NULL,longitude REAL NOT NULL,radius_m INTEGER NOT NULL DEFAULT 1000,status TEXT NOT NULL DEFAULT 'active',sharing_location INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS help_offers(id INTEGER PRIMARY KEY AUTOINCREMENT,help_id INTEGER NOT NULL,helper_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'offered',helper_latitude REAL,helper_longitude REAL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(help_id,helper_id));
CREATE TABLE IF NOT EXISTS help_locations(id INTEGER PRIMARY KEY AUTOINCREMENT,help_id INTEGER NOT NULL,helper_id INTEGER,latitude REAL NOT NULL,longitude REAL NOT NULL,shared_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,type TEXT NOT NULL,title TEXT NOT NULL,message TEXT NOT NULL,link TEXT,read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS private_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,sender_id INTEGER NOT NULL,receiver_id INTEGER NOT NULL,content TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rooms(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,owner_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS room_members(room_id INTEGER,user_id INTEGER,member_role TEXT NOT NULL DEFAULT 'member',joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(room_id,user_id));
CREATE TABLE IF NOT EXISTS moderation_cases(id INTEGER PRIMARY KEY AUTOINCREMENT,reporter_id INTEGER,target_type TEXT NOT NULL,target_id INTEGER,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',resolution TEXT,reviewed_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at TEXT);
CREATE TABLE IF NOT EXISTS authority_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,institution TEXT NOT NULL,authority_type TEXT NOT NULL,position TEXT NOT NULL,area TEXT,institutional_code TEXT,institutional_email TEXT,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',reviewed_by INTEGER,reviewed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS authority_documents(id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER NOT NULL,file_path TEXT NOT NULL,original_name TEXT,mime TEXT,size INTEGER);
CREATE TABLE IF NOT EXISTS points(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,amount INTEGER NOT NULL,reason TEXT NOT NULL,object_type TEXT,object_id INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS badges(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,description TEXT NOT NULL,icon TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_badges(user_id INTEGER,badge_id INTEGER,awarded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,badge_id));
CREATE TABLE IF NOT EXISTS missions(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT NOT NULL,points INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS mission_progress(mission_id INTEGER,user_id INTEGER,progress INTEGER NOT NULL DEFAULT 0,completed INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(mission_id,user_id));
CREATE TABLE IF NOT EXISTS learning_modules(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,topic TEXT NOT NULL,body TEXT NOT NULL,points INTEGER NOT NULL DEFAULT 20,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS learning_questions(id INTEGER PRIMARY KEY AUTOINCREMENT,module_id INTEGER NOT NULL,question TEXT NOT NULL,options_json TEXT NOT NULL,correct_index INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS learning_results(id INTEGER PRIMARY KEY AUTOINCREMENT,module_id INTEGER NOT NULL,user_id INTEGER NOT NULL,score INTEGER NOT NULL,points_awarded INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id INTEGER,action TEXT NOT NULL,object_type TEXT,object_id INTEGER,details TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT NOT NULL,name TEXT NOT NULL,UNIQUE(type,name));
CREATE TABLE IF NOT EXISTS commands(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,description TEXT NOT NULL,syntax TEXT NOT NULL,example TEXT,permission_code TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS authority_reinforcements(id INTEGER PRIMARY KEY AUTOINCREMENT,requester_id INTEGER NOT NULL,target_authority_type TEXT NOT NULL,reason TEXT NOT NULL,priority TEXT NOT NULL,description TEXT NOT NULL,latitude REAL,longitude REAL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS support_tickets(id INTEGER PRIMARY KEY AUTOINCREMENT,public_id TEXT UNIQUE NOT NULL,user_id INTEGER NOT NULL,subject TEXT NOT NULL,category TEXT NOT NULL,message TEXT NOT NULL,priority TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',assigned_to INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ticket_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,ticket_id INTEGER NOT NULL,sender_id INTEGER NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_users_status ON users(status);CREATE INDEX IF NOT EXISTS idx_users_authority_type ON users(authority_type);CREATE INDEX IF NOT EXISTS idx_reports_status ON reports(status);CREATE INDEX IF NOT EXISTS idx_report_history_report ON report_history(report_id);CREATE INDEX IF NOT EXISTS idx_help_status ON help_requests(status);CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,read_at);CREATE INDEX IF NOT EXISTS idx_audit_time ON audit_logs(created_at);
